def write_request(text):
    data = list(text.encode("utf-8")) + [10]
    return {"rax": 1, "rdi": 1, "rdx": len(data), "bytes": data}

unitTests:
@test("Hi")
def _():
    check_eq(write_request("Hi"), {"rax": 1, "rdi": 1, "rdx": 3, "bytes": [72, 105, 10]})

@test("an empty print still sends the new line")
def _():
    check_eq(write_request(""), {"rax": 1, "rdi": 1, "rdx": 1, "bytes": [10]})

@test("bytes, not characters")
def _():
    request = write_request("é😀")
    check_eq(request["rdx"], 7)
    check_eq(request["bytes"], [0xC3, 0xA9, 0xF0, 0x9F, 0x98, 0x80, 10])

